// Pull out what /api/email-reply needs, and DROP anything without a +q tag.
//
// THE GUARD IS THE POINT OF THIS NODE. john@callplaybook.com is a real person's mailbox. The
// trigger's Gmail query narrows things already, but a query is a filter, not a guarantee. If it
// ever over-matches, this stops personal mail being written into an operator-facing inbox in the
// app. Deliberate trade: a reply whose + was mangled by some relay is dropped rather than stored
// unattributed. Keeping strangers' mail out of the Replies tab matters more, and the message is
// still sitting in Gmail either way.

const j = $input.item.json;

// n8n parses the message with mailparser when simple:false, so an address field can arrive as a
// STRING, as { text }, or as { value: [{ address }] }. Reading it raw yields '[object Object]' and
// the tag test below silently never matches -- every reply would be dropped.
function addrText(v) {
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'object') {
    if (typeof v.text === 'string' && v.text) return v.text;
    if (Array.isArray(v.value)) {
      let out = '';
      for (const x of v.value) {
        if (x && x.address) out = out ? out + ', ' + x.address : x.address;
      }
      return out;
    }
  }
  return '';
}

// Headers may be a Map (mailparser), a plain object, or Gmail's [{name,value}] array.
function header(name) {
  const want = String(name).toLowerCase();
  const h = j.headers || (j.payload && j.payload.headers);
  if (!h) return '';
  if (Array.isArray(h)) {
    for (const x of h) {
      if (x && String(x.name || '').toLowerCase() === want) return addrText(x.value);
    }
    return '';
  }
  if (typeof h.get === 'function') { return addrText(h.get(want)); }
  for (const k of Object.keys(h)) {
    if (k.toLowerCase() === want) return addrText(h[k]);
  }
  return '';
}

const to = addrText(j.to) || header('to');
const deliveredTo = header('delivered-to');
const cc = addrText(j.cc) || header('cc');

// Must match TAG and the id format in lib/reply-address.js.
const TAG = /\+q[0-9a-f]{32}(?:@|$|[,>\s])/i;
let tagged = '';
for (const v of [to, deliveredTo, cc]) {
  if (v && TAG.test(v)) { tagged = v; break; }
}
if (!tagged) return null;   // not a blast reply -- leave it alone

return {
  json: {
    // Gmail's immutable message id. The endpoint writes it to provider_message_id, which is
    // UNIQUE, so a re-poll or a re-run reconciles instead of posting the reply twice.
    id: j.id || j.messageId || null,
    threadId: j.threadId || null,
    from: addrText(j.from) || header('from') || null,
    to: tagged,
    cc: cc || null,
    subject: j.subject || header('subject') || null,
    text: j.text || j.textPlain || j.snippet || null,
    html: j.html || j.textAsHtml || null,
    // Epoch millis as a string. The endpoint normalises it; handed straight to a timestamptz
    // column this would store a date tens of thousands of years from now.
    internalDate: j.internalDate || null,
    date: j.date || header('date') || null,
  },
};
